var acym_helperNotification = {
  setNotificationCenter: function setNotificationCenter() {
    var $button = jQuery('.acym__header__notification');
    if ($button.find('i').hasClass('acymicon-check-circle')) {
      setTimeout(function () {
        $button.find('> i').attr('class', 'acymicon-bell');
        $button.find('.acym__tooltip__text').remove();
        $button.removeAttr('data-acym-tooltip').removeAttr('data-acym-tooltip-position').removeClass('acym__header__notification__button__success acym__header__notification__pulse');
      }, 8000);
    }
    $button.off('click').on('click', function () {
      acym_helperNotification.readFullNotification();
      var $notifButton = jQuery(this);
      var $notificationCenter = jQuery('.acym__header__notification__center');
      var notifButtonOffset = $notifButton.offset();
      var left = notifButtonOffset.left - $notificationCenter.width() + $notifButton.width() + 'px';
      if (jQuery('html').attr('dir') === 'rtl') {
        left = '42px';
      }
      $notificationCenter.css({
        'top': notifButtonOffset.top + $notifButton.height() + 10 + 'px',
        'left': left
      }).addClass('acym__header__notification__center__visible');
      var ajaxUrl = ACYM_AJAX_URL + '&ctrl=configuration&task=markNotificationRead';
      jQuery.post(ajaxUrl, function (res) {
        jQuery('.acym__header__notification').removeClass('acym__header__notification__pulse acym__header__notification__button__success acym__header__notification__button__info acym__header__notification__button__warning acym__header__notification__button__error').find('> i').attr('class', 'acymicon-bell');
      });
      $button.off('click').on('click', function (e) {
        if (jQuery(e.target).hasClass('acym__header__notification__center__visible') || jQuery(e.target).closest('.acym__header__notification__center__visible').length > 0) {
          return true;
        }
        acym_helperNotification.removeNotificationsCenter();
      });
      setTimeout(function () {
        jQuery(window).off('click').on('click', function (e) {
          if (jQuery(e.target).hasClass('acym__header__notification__center__visible') || jQuery(e.target).closest('.acym__header__notification__center__visible').length > 0) {
            return true;
          }
          acym_helperNotification.removeNotificationsCenter();
        });
      }, 100);
    });
    jQuery('.acym__message__close').off('click').on('click', function () {
      var $closeButton = jQuery(this);
      var id = $closeButton.attr('data-id');
      if (id !== undefined && id != 0) {
        var ajaxUrl = ACYM_AJAX_URL + '&ctrl=configuration&task=markNotificationRead&id=' + id;
        jQuery.post(ajaxUrl, function (res) {
          $closeButton.closest('.acym__message').remove();
        });
      } else {
        $closeButton.closest('.acym__message').remove();
      }
    });
  },
  removeNotifications: function removeNotifications() {
    jQuery(document).on('click', '.acym__header__notification__one__delete, .acym__header__notification__toolbox__remove, .acym__dashboard__notification__delete, .acym__do__not__remindme', function () {
      var isDashboardNotif = jQuery(this).hasClass('acym__dashboard__notification__delete') || jQuery(this).hasClass('acym__do__not__remindme');
      var id = jQuery(this).attr('data-id');
      if (!id) {
        id = jQuery(this).attr('title');
      }
      var ajaxUrl = ACYM_AJAX_URL + '&ctrl=configuration&task=removeNotification&id=' + id;
      jQuery.post(ajaxUrl, function (res) {
        res = acym_helper.parseJson(res);
        if (!res.error) {
          acym_helperNotification.refreshDashboardNotifications(res.data.dashboardNotifications);
          if (!isDashboardNotif) {
            jQuery('.acym__header__notification__center').html(res.data.headerHtml);
            jQuery('.acym__header__notification').find('> i').attr('class', 'acymicon-bell');
          }
        } else {
          console.log('Error removing notification:', res.message);
        }
      });
      if (!isDashboardNotif) {
        jQuery('.acym__header__notification').removeClass('acym__header__notification__pulse acym__header__notification__button__success acym__header__notification__button__info acym__header__notification__button__warning acym__header__notification__button__error').find('> i').attr('class', 'acymicon-bell');
      }
    });
  },
  refreshDashboardNotifications: function refreshDashboardNotifications(notifications) {
    if (notifications.length === 0) {
      jQuery('#acym__dashboard__notifications').remove();
      return;
    }
    var $container = jQuery('.acym__dashboard__notifications').empty();
    notifications.forEach(function (notification) {
      var icon = notification.level === 'warning' ? 'acymicon-exclamation-triangle' : 'acymicon-exclamation-circle';
      var $notification = jQuery('<div>', {
        'class': 'cell grid-x acym__dashboard__notification acym__dashboard__notification__' + notification.level
      }).append(jQuery('<div>', {
        'class': 'cell shrink small-1 align-center grid-x acym__dashboard__notification__icon'
      }).append(jQuery('<i>', {
        'class': 'cell shrink ' + icon
      }))).append(jQuery('<div>', {
        'class': 'cell grid-x small-10'
      }).append(jQuery('<p>', {
        'class': 'cell acym__dashboard__notification__message'
      }).html(notification.message)).append(jQuery('<div>', {
        'class': 'cell acym__dashboard__notification__date'
      }).text(notification.date)));
      if (notification.removable) {
        $notification.append(jQuery('<i>', {
          'class': 'cell shrink small-1 acym__dashboard__notification__delete acymicon-close',
          'data-id': notification.name
        }));
      }
      $container.append($notification, jQuery('<span>', {
        'class': 'acym__dashboard__light__separator separator'
      }));
    });
  },
  removeNotificationsCenter: function removeNotificationsCenter() {
    jQuery('.acym__header__notification__center').removeClass('acym__header__notification__center__visible');
    jQuery(window).off('click');
    acym_helperNotification.setNotificationCenter();
  },
  addNotification: function addNotification(message, type, clear) {
    if (clear === undefined) clear = false;
    if (clear) {
      jQuery('.acym__message').remove();
    }
    if (type === undefined || jQuery.inArray(type, ['success', 'warning', 'error']) == -1) {
      type = 'info';
    }
    var headerNotif = acym_helperNotification.addHeaderNotification(message, type);
    jQuery('#acym_header').after(headerNotif);
    var ajaxUrl = ACYM_AJAX_URL + '&ctrl=configuration&task=addNotification&message=' + message + '&level=' + type;
    jQuery.post(ajaxUrl, function (res) {
      res = acym_helper.parseJson(res);
      if (!res.error) {
        jQuery('.acym__header__notification').replaceWith(res.data.notificationCenter);
        acym_helperNotification.setNotificationCenter();
      } else {
        console.log(res.message);
      }
    });
  },
  addHeaderNotification: function addHeaderNotification(message, type) {
    var structure = '<div class="acym__message grid-x acym__message__' + type + '">' + '<div class="cell auto">' + '<p>' + message + '</p>' + '</div>' + '<i data-id="0" class="cell shrink acym__message__close acymicon-close"></i>' + '</div>';
    return structure;
  },
  readFullNotification: function readFullNotification() {
    jQuery('.acym__header__notification__one').off('click').on('click', function () {
      var $messageTag = jQuery(this).find('.acym__header__notification__message');
      var messageInAttribute = $messageTag.attr('data-acym-full');
      if (acym_helper.empty(messageInAttribute)) return true;
      var messageInTag = $messageTag.html();
      $messageTag.html(messageInAttribute);
      $messageTag.attr('data-acym-full', messageInTag);
    });
  }
};
